while :; do
  for n in 0 1 2; do
    port=$((8000+n))
    if ! (exec 3<>/dev/tcp/127.0.0.1/$port) 2>/dev/null; then PORT=$port NODE_ID=$n python3 /app/server.py >/tmp/huddle-$n.log 2>&1 & pids="$pids $!"; fi
  done
  sleep 1
done
